// Same optional search as the frozen benchmark. Both arms visit the same minimal legal prefixes. No six-hit test.
#[allow(dead_code)] mod shared {include!("ramsey_six_hit_search.rs");
pub fn flips(a:&mut A,e:E){toggle(a,e)}pub fn ok(a:&A,e:E)->bool{safe(a,e)}pub fn descend(a:&mut A,p:&[E],need:usize,z:usize,s:&mut[u64;6]){solve(a,p,need,z,s)}
pub fn coverage(g:&A,p:&[E])->bool{let mut fixed=*g;for &e in p{toggle(&mut fixed,e)}let mut rows=vec![];sets(&fixed,F,7,0,&mut rows);let n=rows.len();if n<8{return false}let w=(n+63)/64;let mut all=vec![!0u64;w];if n%64!=0{all[w-1]=(1<<(n%64))-1}let mut adj=vec![all.clone();n];let mut seven=vec![];sets(g,F,7,0,&mut seven);for q in seven{let mut mask=vec![0;w];let mut missed=vec![];for(i,&s)in rows.iter().enumerate(){if q&s==0{missed.push(i);mask[i/64]|=1<<(i%64)}}for i in missed{for j in 0..w{adj[i][j]&=!mask[j]}}}for i in 0..n{adj[i][i/64]&=!(1<<(i%64))}clique(&adj,all,8)}}
use std::{io::{self,Read},time::Instant};use shared::{flips,ok};type E=(usize,usize);type A=[u32;26];
struct Site{z:usize,rows:bool,audit:bool,old:Vec<E>,counts:[u64;6],ns:[u128;2],prefixes:usize}
impl Site{fn walk(&mut self,g:&mut A,tri:&[Vec<E>],cut:&mut Vec<E>,ban:&mut Vec<E>){if let Some(t)=tri.iter().find(|t|!t.iter().any(|e|cut.contains(e))){let n=ban.len();for &e in t{if ban.contains(&e)||!ok(g,e){continue}flips(g,e);cut.push(e);self.walk(g,tri,cut,ban);cut.pop();flips(g,e);ban.push(e)}ban.truncate(n);return}if cut.iter().any(|e|!tri.iter().any(|t|t.contains(e)&&t.iter().filter(|f|cut.contains(f)).count()==1)){return}self.prefixes+=1;let es=g.iter().map(|s|s.count_ones()as usize).sum::<usize>()/2;let opt:Vec<_>=self.old.iter().copied().filter(|&(i,j)|g[i]>>j&1!=0 && ok(g,(i,j))).collect();if self.rows{let start=Instant::now();let keep=shared::coverage(g,&opt);self.ns[0]+=start.elapsed().as_nanos();if !keep{return}}let n=self.counts[5];let t=Instant::now();if es>=76{shared::descend(g,&opt,es-76,self.z,&mut self.counts)}self.ns[1]+=t.elapsed().as_nanos();if self.audit{println!("audit {} {} {} {}",self.z,es,opt.len(),self.counts[5]-n)}}}
fn main(){let args:Vec<_>=std::env::args().collect();let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let b:Vec<u32>=s.split_whitespace().map(|x|x.parse().unwrap()).collect();for z in 0..27{let vs:Vec<_>=(0..27).filter(|&i|i!=z).collect();let mut a=[0;26];let mut old=vec![];let mut cross=vec![];for i in 0..26{for j in i+1..26{if b[vs[i]]>>vs[j]&1!=0{old.push((i,j));flips(&mut a,(i,j))}else if (b[z]>>vs[i]^b[z]>>vs[j])&1!=0{cross.push((i,j))}}}let mut site=Site{z,rows:args[1]=="rows",audit:args[2]=="audit",old,counts:[0;6],ns:[0;2],prefixes:0};for(k,&e)in cross.iter().enumerate(){for &f in &cross[k+1..]{let mut g=a;flips(&mut g,e);flips(&mut g,f);let mut tri=vec![];for &(i,j)in &[e,f]{let mut m=g[i]&g[j];while m!=0{let t=m.trailing_zeros()as usize;m&=m-1;let mut v:Vec<_>=[(i,t),(j,t)].iter().map(|&(u,v)|(u.min(v),u.max(v))).filter(|x|*x!=e&&*x!=f).collect();v.sort();if !tri.contains(&v){tri.push(v)}}}site.walk(&mut g,&tri,&mut vec![],&mut vec![])}}println!("done {} {} {} {} {} {}",z,site.prefixes,site.counts[4],site.counts[5],site.ns[0],site.ns[1])}}
